//! dimuli app: Slint UI, state and platform glue around `collage-core`.
//!
//! Data flows one way: UI callback or [`platform::PlatformEvent`] -> controller -> `AppState` / core -> view
//! models -> Slint properties.

mod controller;
mod images;
pub mod platform;
mod state;
mod texts;
mod view;

// The code generated by `slint_build` uses `unwrap`, `panic!` and indexing. It is not ours to change,
// so the workspace lints are relaxed for this module only; hand-written code stays fully covered.
#[allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
mod ui {
    slint::include_modules!();
}

use std::rc::Rc;

use platform::Platform;
use slint::ComponentHandle;

/// Creates the window, wires it to the controller and runs the event loop until the window is closed.
pub fn run(platform: Rc<dyn Platform>) -> Result<(), slint::PlatformError> {
    let window = ui::AppWindow::new()?;
    let _controller = controller::Controller::install(&window, platform);
    window.run()
}
